const reverse = route => [...route].reverse();
const sound = (incoming, outgoing = reverse(incoming), names = ['Gelen konuşma', 'Dönen konuşma']) => ({ incoming, outgoing, names });
const step = (title, text, message, path, options = {}) => ({ title, text, message, path, type: 'sip', duration: 4200, ...options });
const callerLeg = [N.caller, N.operator, N.pbx];
