function entry() {
  return [step('Müşteri kurumun numarasını arar', 'Arama önce operatöre ulaşır. Henüz personelle veya YZ ile bir ses köprüsü kurulmadı.', 'Arama isteği', [N.caller, N.operator], { type: 'access' }),
    step('Operatör çağrıyı santrale getirir', 'Santral aranan numarayı kontrol eder ve gelen çağrı rotasını seçer.', 'INVITE · kurumun ana numarası', [N.operator, N.pbx])];
}
function targetSetup(target, source, audio = null) {
  const tail = target.id === '301' ? [N.switch, N.ata] : target.tail;
  const prefix = source === N.vera ? [N.vera, N.pbx] : [N.pbx];
  const requestPath = [...prefix, ...tail];
  const steps = [step(`${target.id} aranıyor`, `Santral çağrıyı ${target.id === '301' ? '301 hesabına kayıtlı ATA’ya' : target.label + ' telefonuna'} switch üzerinden gönderir.`, `INVITE · ${target.id}`, requestPath, { audio })];
  if (target.id === '301') steps.push(step('ATA analog telefonu çaldırır', 'ATA, FXS portundan RJ11 kabloya zil sinyali verir. Bu kabloda SIP veya RTP paketi yoktur.', 'Analog zil sinyali', [N.ata, N.analog], { type: 'analog', audio }));
  steps.push(step('Çalma bilgisi geri döner', '180 Ringing, hedefin çaldığını bildirir. Cevaplanmadan müşteri sesi bu telefona bağlanmaz.', '180 Ringing', source === N.pbx ? [...reverse(requestPath), N.operator] : reverse(requestPath), { audio }));
  if (target.id === '301') steps.push(step('Personel analog ahizeyi açar', 'ATA hat akımındaki değişimi algılar. Analog off-hook olayını SIP cevabına dönüştüren cihaz ATA’dır.', 'Analog off-hook', [N.analog, N.ata], { type: 'analog', audio }));
  steps.push(step('Personel cevap verdi', '200 OK, aranan çağrı bacağının cevaplandığını bildirir. SDP medya adresi, port ve codec bilgisini içerir.', '200 OK · INVITE cevabı', source === N.pbx ? [...reverse(requestPath), N.operator] : reverse(requestPath), { audio }));
  steps.push(step('Cevaplanan bacak onaylanır', 'ACK ile INVITE işlemi tamamlanır. Artık cevaplanan çağrı bacakları arasında ses taşınabilir.', 'ACK', source === N.pbx ? [N.operator, ...requestPath] : requestPath, { audio }));
  return steps;
}
export function scenarioFor(...args) {
  return withOfficeNetwork(rawScenarioFor(...args),{N,nodes,connections});
}
function rawScenarioFor(id, destination = '201', registrationMode = 'phones', directMode = 'sip', pbxMode = 'normal', lineType = 'fixed', staffType = 'mobile', modelMode = 'pipeline', pbxLocation = 'cloud', phoneLocation, fxoTarget = '301') {
  if(id==='public-line'&&lineType==='fxo')return fxoScenario(fxoTarget,{N});
  if (id === 'public-line') return publicLineScenario(lineType,staffType,{N,connections});
  if(id==='direct'&&phoneLocation){const raw=directMode==='forward'?forwardingScenario(directScenario(),N):directScenario();return phoneConnectionScenario(directMode,phoneLocation,{N,base:withOfficeNetwork(raw,{N,nodes,connections})});}
  if (id === 'direct') { const base=directScenario(); return directMode === 'forward' ? forwardingScenario(base,N) : base; }
  if (id === 'registration') return registrationScenario(registrationMode);
  const target = targets.find(item => item.id === destination) || targets[0];
  if (id === 'mechanism') return platformScenario(modelMode,{N});
  if(id==='pbx'&&['local-sip','remote-sip','vpn-sip','ari'].includes(pbxMode))return pbxConnectionScenario(pbxMode,target,pbxLocation,{N});
  if (id === 'pbx' && pbxMode === 'sip-number') return sipNumberScenario(target,{N,connections});
  if (id === 'pbx') {
    const setup = targetSetup(target, N.pbx);
    // The PBX forwards/recreates responses on its separate operator leg.
    const phases = [...entry(), ...setup,
      step('Müşteri ve personel konuşuyor', 'Gelen ses operatör ve santral üzerinden dahiliye ulaşır. Personelin sesi ters yönden müşteriye döner. Analog hedefte RTP ↔ analog dönüşümünü ATA yapar.', 'Çift yönlü konuşma', humanLeg(target), { type: 'media', duration: 6500, audio: sound(humanLeg(target), undefined, ['Müşteri → personel', 'Personel → müşteri']), final: true })];
    return { id, target, phases, title: tabs.find(tab => tab.id === 'pbx').title };
  }
  if (id === 'reception') {
    const waiting = holdAt(N.vera);
    const phases = [...entry(),
      step('Santral IVR yerine Verasist’i seçer', 'Ana numaranın gelen çağrı hedefi Verasist trunk’ına ayarlanmıştır. Telefonlar kurum santraline bağlı kalır.', 'INVITE · Verasist ajan hedefi', [N.pbx, N.vera]),
      step('Verasist çağrıyı cevaplar', 'Verasist’in 200 OK cevabı kurum santraline gelir; santral operatör bacağını da cevaplar. Her bacak kendi SIP işlemini yürütür.', '200 OK · YZ cevapladı', [N.vera, N.pbx, N.operator]),
      step('Müşteri ile YZ arasında medya kurulur', 'ACK santral üzerinden Verasist’e ulaşır. RTP görüşmesi artık kurulabilir; SIP mesajı sesin kendisi değildir.', 'ACK', [N.operator, N.pbx, N.vera]),
      step('YZ ilk karşılamayı yapar', '“Merhaba, nasıl yardımcı olabilirim?” Yanıt sesi Verasist → kurum santrali → operatör → müşteri yolundan gider.', 'YZ’nin karşılama sesi', reverse(veraLeg), { type: 'media', duration: 6000, audio: { outgoing: reverse(veraLeg), incoming: [], names: ['Müşteri henüz konuşmuyor', 'YZ → müşteri'] } }),
      step('Müşteri istediği bölümü söyler', `Müşterinin sesi aynı yolun tersinden Verasist’e gelir. YZ isteği anlar ve kurum rehberinden ${target.id} hedefini bulur.`, 'Müşterinin konuşması', veraLeg, { type: 'media', duration: 6000, audio: { incoming: veraLeg, outgoing: [], names: ['Müşteri → YZ', ''] } }),
      step('YZ aktarım kararını verir', `Call Transfer aracı ${target.id} hedefini seçer. Bu bir uygulama işlemidir; müşterinin ses paketi değildir.`, `Call Transfer · ${target.id}`, [N.vera], { type: 'internal', audio: sound(veraLeg, undefined, ['Müşteri → YZ', 'YZ’nin aktarım anonsu']) }),
      ...targetSetup(target, N.vera, waiting),
      step('İki çağrı bacağı köprülenir', 'Verasist müşteri bacağı ile cevaplanan personel bacağını birleştirir. YZ konuşmayı bırakır; medya bu örnekte Verasist köprüsü üzerinden taşınır.', 'Bridge · müşteri + personel', [N.vera], { type: 'internal', audio: waiting }),
      step('Müşteri ve personel konuşuyor', 'Ses, gelen ve dönüş çağrı bacaklarını Verasist köprüsünde birleştirir. Aynı santral/trunk iki ayrı bacağı taşır. YZ artık konuşmaya katılmaz.', 'Personelle çift yönlü ses', bridgedLeg(target), { type: 'media', duration: 6500, audio: sound(bridgedLeg(target), undefined, ['Müşteri → personel', 'Personel → müşteri']), final: true })];
    return { id, target, phases, title: 'İlk karşılama' };
  }
  if (id === 'extension') {
    const staff = targets[0], holding = holdAt(N.pbx);
    const phases = [...entry(), ...targetSetup(staff, N.pbx),
      step('Müşteri önce personelle konuşur', 'Müşteri ile IP 201 arasında normal görüşme kurulmuştur. Personel, çağrıyı Verasist YZ’ye aktarmaya karar verir.', 'Müşteri ↔ IP 201', humanLeg(staff), { type: 'media', duration: 5500, audio: sound(humanLeg(staff), undefined, ['Müşteri → 201', '201 → müşteri']) }),
      step('Personel 700’e aktarım ister', 'Telefon santrale REFER gönderir; Refer-To hedefi 700’dür. Bu örnek REFER destekli telefon/santral kullanır. Bazı sistemlerde aktarım özellik koduyla yapılır.', 'REFER · Refer-To: 700', [N.ip201, N.switch, N.pbx], { audio: holding }),
      step('Santral aktarım isteğini kabul eder', '202 Accepted yalnızca REFER isteğinin kabulüdür. Verasist’in cevapladığı veya aktarımın bittiği anlamına gelmez.', '202 Accepted · REFER cevabı', [N.pbx, N.switch, N.ip201], { audio: holding }),
      step('700 hedefi Verasist’e yönlendirilir', 'Santraldeki 700 sanal hedefi, kuruma atanan Verasist ajan numarasına eşlenir. Santral Verasist’e ayrı bir çağrı bacağı açar.', 'INVITE · 700 → ajan hedefi', [N.pbx, N.vera], { audio: holding }),
      step('Verasist yeni çağrı bacağını cevaplar', 'Verasist 200 OK gönderir. Bu, REFER’ın değil yeni INVITE’ın cevabıdır.', '200 OK · Verasist INVITE', [N.vera, N.pbx], { audio: holding }),
      step('Santral Verasist bacağını onaylar', 'ACK, yeni Verasist çağrı bacağını tamamlar. Müşteri hattı korunurken yeni hedefle köprü kurulabilir.', 'ACK · Verasist bacağı', [N.pbx, N.vera], { audio: holding }),
      step('Aktarım sonucu personele bildirilir', 'Santral REFER sonucunu NOTIFY ile bildirir. Gövdedeki SIP/2.0 200 OK aktarım hedefinin sonucudur; NOTIFY’ın kendi cevabı değildir.', 'NOTIFY · aktarım başarılı', [N.pbx, N.switch, N.ip201], { audio: holding }),
      step('Telefon sonuç bildirimini onaylar', '201, NOTIFY mesajını 200 OK ile yanıtlar. SIP mesajları CSeq yöntemiyle birbirinden ayrılır.', '200 OK · NOTIFY cevabı', [N.ip201, N.switch, N.pbx], { audio: holding }),
      step('Personelin eski bacağı kapatılır', 'Bu örnekte santral personel bacağını BYE ile kapatır. Müşterinin bacağı kapanmaz; Verasist’e aktarılır.', 'BYE · eski personel bacağı', [N.pbx, N.switch, N.ip201], { audio: holding }),
      step('Eski bacağın kapanışı onaylanır', 'Telefon BYE isteğine 200 OK döndürür. Müşteri artık personelin değil Verasist’in karşısındadır.', '200 OK · BYE cevabı', [N.ip201, N.switch, N.pbx], { audio: holding }),
      step('700 numaralı YZ müşteriyle konuşur', 'Müşterinin sesi operatör → kurum santrali → Verasist yolundan akar. YZ’nin yanıtı tersinden döner. IP 201 bu ses yolundan ayrılmıştır.', 'Müşteri ↔ Verasist / 700', veraLeg, { type: 'media', duration: 6500, audio: sound(veraLeg, undefined, ['Müşteri → YZ / 700', 'YZ / 700 → müşteri']), final: true })];
    return { id, target: staff, phases, title: 'Dahili ajan' };
  }
  return rawScenarioFor('pbx', destination);
}



function directScenario() {
  const registration = [N.ip201,N.switch,N.operator];
  const phoneLeg = [N.operator,N.switch,N.ip201];
  const staffPhoneLeg = [N.operator,N.switch,N.ip202];
  const baselineAudio = [N.caller,N.operator,N.switch,N.ip201];
  const aiAudio = [N.caller,N.operator,N.vera];
  const staffAudio = [N.caller,N.operator,N.vera,N.operator,N.switch,N.ip202];
  const held = sound(aiAudio,reverse(aiAudio),['Müşteri → Verasist','Verasist / bekleme anonsu → müşteri']);
  const staffAccount='office-a-202@operator.example.invalid';
  const account='office-a-201@operator.example.invalid',main='12025550101@verasist.example.invalid',staff='12025550201@operator.example.invalid',caller='customer@operator.example.invalid';
  const legs={registration:{from:account,to:account,sender:'192.0.2.21',receiver:'203.0.113.20'},baseline:{from:main,to:account,sender:'203.0.113.20',receiver:'198.51.100.24'},customer:{from:caller,to:main,sender:'203.0.113.20',receiver:'203.0.113.10'},staff:{from:main,to:staff,sender:'203.0.113.10',receiver:'203.0.113.20'},'staff-phone':{from:main,to:staffAccount,sender:'203.0.113.20',receiver:'198.51.100.24'}};
  const sip=(method,leg,{status,seq=1,uri,headers='',media=false}={})=>{
    const l=legs[leg],bye=method==='BYE',isResponse=Boolean(status),swap=bye;
    const from=swap?l.to:l.from,to=swap?l.from:l.to;
    const first=status?`SIP/2.0 ${status}`:`${method} sip:${uri || (method==='REGISTER'?'operator.example.invalid':to)} SIP/2.0`;
    const address=isResponse?l.receiver:l.sender;
    const body=media?`v=0\r\no=- 1 1 IN IP4 ${address}\r\ns=demo\r\nc=IN IP4 ${address}\r\nt=0 0\r\nm=audio ${address==='198.51.100.24'?(leg==='staff-phone'?24002:24000):10000} RTP/AVP 0\r\na=rtpmap:0 PCMU/8000\r\na=sendrecv\r\n`:'';
    const via=bye?l.receiver:l.sender;
    const toTag=isResponse || method==='ACK' || bye?`;tag=${swap?'a':'b'}`:'';
    return [first,`Via: SIP/2.0/UDP ${via}:5060;branch=z9hG4bK-${leg}-${method}-${seq};rport`,`From: <sip:${from}>;tag=${swap?'b':'a'}`,`To: <sip:${to}>${toTag}`,`Call-ID: direct-${leg}-demo@example.invalid`,`CSeq: ${seq} ${method}`,headers,media?'Content-Type: application/sdp':'',`Content-Length: ${new TextEncoder().encode(body).length}`].filter(Boolean).join('\r\n')+'\r\n\r\n'+body;
  };
  const make=stage=>(title,text,message,path,code,en,options={})=>step(title,text,message,path,{type:'direct',code,en,stage,...options});
  const a=make('operator'),b=make('verasist');
  const phases=[
    a('Önce yalnızca operatör ve IP telefon var','Kurumda santral yoktur. IP telefon kaydı ve dış numara hizmeti sunan bir operatör seçilmiş varsayılır. Telefonun SIP hesabını operatör sağlar; modem yalnızca internet/NAT erişimidir. Bu ilk aşamada Verasist yoktur.','1. aşama · operatör + IP telefon',[N.operator],'Registrar: operator.example.invalid\nTelefon hesabı: office-a-201\nDış numara: operatör hizmeti\nVerasist: henüz yok',['Start with just the operator and IP phone','There is no office PBX. This example assumes an operator that supports phone registration and a public number. The operator supplies the SIP account; the router only provides internet/NAT access. Verasist is not present yet.','Registrar: operator.example.invalid\nPhone account: office-a-201\nPublic number: operator service\nVerasist: not present yet']),
    a('Telefona operatör hesabı girilir','201 telefonuna operatörün SIP sunucu adresi, kullanıcı adı ve parolası girilir. Telefon Verasist’e kaydolmaz. İkinci telefon varsa ayrı hesabı olur; kurumda ayrıca santral kurulmaz.','Telefon → operatör hesabı',[N.ip201],'Server: operator.example.invalid\nUsername: office-a-201\nPassword: <gizli>',['Configure the operator account on the phone','Enter the operator SIP server, username and password on phone 201. The phone does not register with Verasist. A second phone uses a separate account; the office needs no separate PBX.','Server: operator.example.invalid\nUsername: office-a-201\nPassword: <secret>']),
    a('IP telefon operatöre REGISTER gönderir','Kayıt isteği telefon → modem/NAT → operatör yolundan gider. Contact, telefonun önerdiği ulaşım adresidir. Operatör henüz çağrı kurmaz ve bu aşamada ses akmaz.','REGISTER · operatör hesabı',registration,sip('REGISTER','registration',{headers:'Contact: <sip:office-a-201@192.0.2.21:5060>\r\nExpires: 300'}),['The IP phone sends REGISTER to the operator','Registration travels phone → router/NAT → operator. Contact advertises the phone address. No call or audio starts during registration.']),
    a('Operatör kimlik doğrulama ister','Operatör 401 challenge ile realm ve nonce gönderir. Telefon, operatör hesabının kimliğini doğrulayacaktır; bu mesaj çağrı cevabı değildir.','401 Unauthorized · operatör',reverse(registration),sip('REGISTER','registration',{status:'401 Unauthorized',headers:'WWW-Authenticate: Digest realm="operator", nonce="demo-nonce", algorithm=MD5'}),['The operator requests authentication','The operator returns a 401 challenge with realm and nonce. The phone must authenticate its operator account; this is not an answered call.']),
    a('Telefon operatör hesabını doğrular','Telefon Authorization içeren yeni REGISTER gönderir. Parola başlıkta düz metin taşınmaz; Digest yanıtı operatör hesabına göre hesaplanır.','REGISTER + Authorization',registration,sip('REGISTER','registration',{seq:2,headers:'Authorization: Digest username="office-a-201", realm="operator", nonce="demo-nonce", response="<digest>"\r\nContact: <sip:office-a-201@192.0.2.21:5060>\r\nExpires: 300'}),['The phone authenticates with the operator','The phone sends a new REGISTER with Authorization. The password is not a plain-text header; the Digest response uses the operator account credentials.']),
    a('Operatör telefonun adresini kaydeder','200 OK kayıt işlemini kabul eder. Operatör hesap/Contact eşleşmesini ve kayıt süresini tutar. NAT için görülen kaynak adresi/bağlantı dikkate alınır. Telefon süre dolmadan yenileme yapar; REGISTER için ACK yoktur.','200 OK · REGISTER',reverse(registration),sip('REGISTER','registration',{status:'200 OK',seq:2,headers:'Contact: <sip:office-a-201@192.0.2.21:5060>;expires=300'}),['The operator saves the phone contact','200 OK accepts registration. The operator stores the account/Contact binding and expiry, considering the observed source or flow for NAT. The phone refreshes before expiry. REGISTER does not use ACK.']),
    a('Müşteri dış numarayı arar','Müşterinin araması operatöre ulaşır. Bu ilk çağrıda gelen numaranın hedefi operatöre kayıtlı IP telefondur. Arada Verasist veya kurum santrali bulunmaz.','Müşteri → operatör',[N.caller,N.operator],'Arayan → operatör erişim ağı\nGelen rota: kayıtlı IP telefon',['The customer calls the public number','The operator receives the customer call. For this first call, the number routes to the registered IP phone. Neither Verasist nor an office PBX is in the path.','Caller → operator access network\nInbound route: registered IP phone']),
    a('Operatör kayıtlı telefonu çaldırır','Operatör güncel Contact/NAT ulaşımını kullanarak INVITE gönderir: operatör → modem → IP telefon. Bu örnekte modem çağrı kararı vermez; paketleri telefona ulaştırır.','INVITE · operatör → IP telefon',phoneLeg,sip('INVITE','baseline',{uri:'office-a-201@198.51.100.24:62000',media:true}),['The operator rings the registered phone','The operator sends INVITE using the current Contact/NAT reachability: operator → router → IP phone. The router forwards traffic; it does not choose the call route.']),
    a('Telefon çalma durumunu bildirir','Telefon 180 Ringing gönderir. Operatör müşteriye çalma durumunu iletir. Personel henüz cevaplamadığı için müşteri sesi telefona köprülenmez.','180 Ringing · telefon → operatör',reverse(phoneLeg),sip('INVITE','baseline',{status:'180 Ringing'}),['The phone reports ringing','The phone sends 180 Ringing. The operator reports ringing to the customer. Customer speech is not bridged to the unanswered phone.']),
    a('Personel IP telefonda cevaplar','Telefon 200 OK ve SDP ile cevap verir. Operatör telefon bacağının medya adresini, portunu ve codec bilgisini öğrenir. Verasist hâlâ akışta yoktur.','200 OK + SDP · IP telefon',reverse(phoneLeg),sip('INVITE','baseline',{status:'200 OK',media:true}),['Staff answer on the IP phone','The phone returns 200 OK with SDP. The operator learns the phone leg media address, port and codec. Verasist is still absent.']),
    a('Operatör telefon bacağını onaylar','Operatör ACK gönderir. Artık cevaplanan telefon bacağıyla müşteri erişimi arasında ses taşınabilir. SIP kurulum mesajları ile RTP sesi farklıdır.','ACK · operatör → IP telefon',phoneLeg,sip('ACK','baseline',{uri:'office-a-201@198.51.100.24:62000'}),['The operator acknowledges the phone leg','The operator sends ACK. Audio can now connect customer access to the answered phone leg. SIP setup messages and RTP audio are different traffic.']),
    a('Verasist olmadan müşteri ve telefon konuşur','Bu örnekte operatör medyayı üzerinden geçirir: müşteri → operatör → modem/NAT → IP telefon. Personelin sesi ters yönden döner. Ses yolunda Verasist veya kurum santrali yoktur.','RTP · operatör ↔ IP telefon',baselineAudio,'RTP v2 | PT=0 (PCMU/8000 örneği)\nSequence: 420 → 421\nTimestamp: 160000 → 160160\nSSRC: kaynak başına ayrı\n20 ms: 12 B RTP başlığı + 160 B ses',['The customer and phone talk without Verasist','This example keeps media anchored at the operator: customer → operator → router/NAT → IP phone. Staff audio returns in reverse. Neither Verasist nor an office PBX is in the audio path.','RTP v2 | PT=0 (PCMU/8000 example)\nSequence: 420 → 421\nTimestamp: 160000 → 160160\nSSRC: separate per source\n20 ms: 12 B RTP header + 160 B audio'],{audio:sound(baselineAudio,undefined,['Müşteri → personel','Personel → müşteri']),duration:8000}),
    a('İlk görüşme kapatılır','Personel telefonu kapatınca BYE operatöre gider. Bu örnekte ilk çağrının sesi burada durur. Verasist bir sonraki aşamada, yeni gelen çağrı için eklenecektir.','BYE · ilk telefon görüşmesi',reverse(phoneLeg),sip('BYE','baseline',{seq:2}),['The first call is ended','Staff hang up and send BYE to the operator. First-call audio stops here. Verasist will be introduced for a new incoming call in the next stage.']),
    a('Telefon kayıtlı kalır','Operatör 200 OK ile kapanışı onaylar ve müşteri erişimini sonlandırır. Telefonun REGISTER kaydı silinmez; sonraki çağrılar için operatöre kayıtlı kalır.','200 OK · ilk çağrı bitti',phoneLeg,sip('BYE','baseline',{status:'200 OK',seq:2}),['The phone stays registered','The operator confirms termination with 200 OK and ends customer access. The phone registration is retained for subsequent calls.']),
    b('Şimdi Verasist operatör bağlantısına eklenir','Telefon aynı operatör hesabında kalır. Operatörün ana numaraya gelen çağrıyı Verasist SIP bağlantısına yönlendirmesi ve Verasist’in bu operatör trunk’ını/ajan numarasını tanıması ayarlanır. Bu özellikler operatör hizmetine bağlıdır.','2. aşama · Verasist ekleniyor',[N.operator,N.vera],'Telefon kaydı: hâlâ operatörde\nAna numara gelen rotası: operatör → Verasist\nVerasist: izinli trunk + kurum/ajan numarası\nKurum santrali: yok',['Now add Verasist to the operator connection','The phone stays on the same operator account. Configure the operator to route the main number to the Verasist SIP connection, and configure the authorized trunk and agent number in Verasist. This requires operator support.','Phone registration: still at the operator\nMain-number inbound route: operator → Verasist\nVerasist: authorized trunk + tenant/agent number\nOffice PBX: none']),
    b('Telefona ayrı bir dönüş hedefi tanımlanır','Verasist’in personele aktaracağı hedef ana numara değildir. İkinci IP telefon 202, ayrı office-a-202 hesabıyla operatöre kaydedilir. Operatör ayrı personel numarasını bu ikinci telefona yönlendirmelidir; ilk telefon 201 hedef değildir. Ana numarayı yeniden aramak Verasist’e dönüp döngü oluşturabilir. Böyle bir hedef desteklenmiyorsa bu aktarım modeli uygulanamaz.','Ana numara ≠ personele dönüş hedefi',[N.ip202,N.switch,N.operator],'Ana numara: 12025550101 → Verasist\nPersonel hedefi: 12025550201 → ikinci IP telefon 202\nSIP hesabı: office-a-202; REGISTER operatöre\n201 ana telefon: aktarım hedefi değil\nAlternatif: operatörün izin verdiği ayrı SIP URI\nAynı ana numaraya geri arama: döngü riski',['Define a separate destination for reaching staff','The transfer destination is not the main number. Register a different IP phone, 202, with its own office-a-202 account. The operator must route the separate staff number to this second phone; the original phone 201 is not the destination. Calling the main number again can loop back into Verasist. Without a supported separate destination, this transfer model cannot be used.','Main number: 12025550101 → Verasist\nStaff destination: 12025550201 → second IP phone 202\nSIP account: office-a-202; REGISTER to operator\nOriginal phone 201: not a transfer target\nAlternative: an operator-supported separate SIP URI\nCalling the main number again: loop risk']),
    b('Yeni müşteri çağrısı operatöre gelir','İlk görüşme tamamlandı. Şimdi aynı kurumun ana numarasına yeni bir çağrı gelir. Telefon operatöre kayıtlıdır; gelen ana numaranın yeni hedefi Verasist’tir.','Yeni çağrı · müşteri → operatör',[N.caller,N.operator],'Yeni çağrı → operatör\nAna numara rotası: Verasist',['A new customer call reaches the operator','The first call has ended. A new call now reaches the same office main number. The phone remains registered at the operator, but the main-number inbound route now points to Verasist.','New call → operator\nMain-number route: Verasist']),
    b('Operatör yeni çağrıyı Verasist’e verir','Operatör ana numaranın çağrısını INVITE ile Verasist’e teslim eder. Verasist operatör kimliğini ve aranan kurum/ajan numarasını kontrol eder. IP telefon bu aşamada çalmaz.','INVITE · operatör → Verasist',[N.operator,N.vera],sip('INVITE','customer',{media:true}),['The operator delivers the new call to Verasist','The operator sends the main-number call to Verasist with INVITE. Verasist checks the authorized operator and called tenant/agent number. The IP phone does not ring yet.']),
    b('Verasist müşteri çağrısını cevaplar','Verasist 200 OK ve SDP gönderir. Operatör–Verasist bacağının ses adresi, portu ve codec bilgisi uzlaşılır. Telefonun operatör kaydı bu SIP işleminden ayrıdır.','200 OK + SDP · Verasist → operatör',[N.vera,N.operator],sip('INVITE','customer',{status:'200 OK',media:true}),['Verasist answers the customer call','Verasist returns 200 OK with SDP. The operator–Verasist leg negotiates audio addresses, ports and codecs. Phone registration is separate from this SIP transaction.']),
    b('Operatör Verasist bacağını onaylar','Operatör ACK gönderir. Müşteri ile Verasist arasında konuşma başlayabilir. Telefon kayıtlı olsa da müşterinin sesini henüz almıyor.','ACK · operatör → Verasist',[N.operator,N.vera],sip('ACK','customer'),['The operator acknowledges the Verasist leg','The operator sends ACK. The customer and Verasist can now talk. The registered phone still does not receive customer audio.']),
    b('İlk karşılamayı artık Verasist yapar','Verasist’in karşılama sesi operatör üzerinden müşteriye döner. Bu sekmede Verasist tek nesnedir; iç işlemci veya ayrı medya köprüsü çizilmez. IP telefon bu ses yolunda değildir.','Verasist → operatör → müşteri',reverse(aiAudio),'Verasist yanıt sesi → RTP → operatör → müşteri\nIP telefon: henüz ses yolunda değil',['Verasist now greets the customer','Verasist greeting audio returns through the operator to the customer. This tab shows Verasist as one object, without internal processors or a separate bridge. The IP phone is not in this audio path.','Verasist response audio → RTP → operator → customer\nIP phone: not in the audio path yet'],{audio:sound([],reverse(aiAudio),['','Verasist → müşteri']),duration:6000}),
    b('Müşteri isteğini Verasist’e söyler','Müşteri sesi müşteri → operatör → Verasist yolundan gider; Verasist’in yanıtı ters yönden döner. YZ isteği anlar ve kayıtlı personele yönlendirmeyi seçer.','Müşteri ↔ operatör ↔ Verasist',aiAudio,'Müşteri ↔ operatör ↔ Verasist\nSes: iki yönlü RTP bacağı\nTelefon: operatörde kayıtlı, henüz cevaplamadı',['The customer tells Verasist what they need','Customer audio travels customer → operator → Verasist, and Verasist response audio returns in reverse. The agent understands the request and selects the registered staff destination.','Customer ↔ operator ↔ Verasist\nAudio: bidirectional RTP leg\nPhone: registered with operator, not answered yet'],{audio:sound(aiAudio),duration:6500}),
    b('Verasist ayrı personel hedefini arar','Verasist operatöre yeni INVITE gönderir; hedef ikinci IP telefon 202’ye bağlı ayrı personel numarasıdır. Bu ikinci çağrı bacağıdır. Müşteri mevcut Verasist bacağında bekler; ana numara yeniden aranmaz.','INVITE · Verasist → personel hedefi',[N.vera,N.operator],sip('INVITE','staff',{uri:staff,media:true}),['Verasist calls the separate staff destination','Verasist sends a new INVITE to the operator for the separate staff number assigned to the second IP phone 202. This is a second call leg. The customer stays on the existing Verasist leg; the main number is not called again.'],{audio:held}),
    b('Operatör kayıtlı IP telefonu çaldırır','Operatör personel numarasını office-a-202 hesabının kayıtlı Contact adresine eşler. INVITE modem üzerinden ikinci IP telefon 202’ye gider; ilk telefon 201 çalmaz. Telefon hâlâ operatöre kayıtlıdır; Verasist’te telefon hesabı açılması gerekmez.','INVITE · operatör → ikinci IP telefon 202',staffPhoneLeg,sip('INVITE','staff-phone',{uri:'office-a-202@198.51.100.24:62002',media:true}),['The operator rings the registered IP phone','The operator maps the staff number to the registered Contact of office-a-202 and sends INVITE through the router to the second IP phone 202; original phone 201 does not ring. The phone is still registered with the operator; no phone account in Verasist is required.'],{audio:held}),
    b('Telefonun çalma bilgisi Verasist’e döner','Telefon 180 Ringing’i operatöre gönderir; operatör Verasist bacağına çalma bilgisini iletir. Farklı SIP bacakları kendi Call-ID ve işlemlerini taşır. Müşteri sesi cevaplanmamış telefona bağlanmaz.','180 Ringing · telefon → operatör → Verasist',[N.ip202,N.switch,N.operator,N.vera],sip('INVITE','staff',{status:'180 Ringing'}),['Phone ringing status returns to Verasist','The phone sends 180 Ringing to the operator, which reports ringing on the Verasist leg. Separate SIP legs have their own Call-IDs and transactions. Customer audio is not connected to the unanswered phone.'],{audio:held}),
    b('Personel çağrıyı telefonda cevaplar','Telefon 200 OK ve SDP ile operatöre cevap verir; operatör Verasist personel bacağını cevaplar. Paket örneği operatör–Verasist bacağına aittir; telefon bacağının SDP/Call-ID bilgileri ayrıdır.','200 OK + SDP · personel cevapladı',[N.ip202,N.switch,N.operator,N.vera],sip('INVITE','staff',{status:'200 OK',media:true}),['Staff answer the call on the phone','The phone answers the operator with 200 OK and SDP; the operator answers the Verasist staff leg. The packet example is the operator–Verasist leg; the phone leg has separate SDP and Call-ID data.'],{audio:held}),
    b('Cevaplanan personel bacakları onaylanır','Verasist operatöre, operatör de telefona kendi ACK mesajını gönderir. Cevaplanan müşteri ve personel bacakları artık Verasist tarafında bağlanabilir.','ACK · Verasist → operatör → telefon',[N.vera,N.operator,N.switch,N.ip202],sip('ACK','staff'),['The answered staff legs are acknowledged','Verasist sends ACK to the operator, and the operator sends its own ACK to the phone. The answered customer and staff legs can now be connected by Verasist.'],{audio:held}),
    b('Müşteri ve personel Verasist üzerinden konuşur','Ses müşteri → operatör → Verasist → operatör → modem/NAT → ikinci IP telefon 202 yolundan gider; personelin sesi tersinden döner. Operatör çizimde iki kez geçer çünkü müşteri ve personel ayrı çağrı bacaklarıdır. YZ konuşmadan ayrılır; bu örnekte medya Verasist üzerinden akmaya devam eder.','RTP · müşteri ↔ Verasist ↔ IP telefon',staffAudio,'RTP v2 | PT=0 (PCMU/8000 örneği)\nSequence: 920 → 921\nTimestamp: 320000 → 320160\nSSRC: her kaynak için ayrı\n20 ms: 12 B RTP başlığı + 160 B ses',['Customer and staff talk through Verasist','Audio travels customer → operator → Verasist → operator → router/NAT → IP phone; staff audio returns in reverse. The operator appears twice because customer and staff use separate call legs. The AI stops speaking while media remains anchored at Verasist in this example.','RTP v2 | PT=0 (PCMU/8000 example)\nSequence: 920 → 921\nTimestamp: 320000 → 320160\nSSRC: separate for each source\n20 ms: 12 B RTP header + 160 B audio'],{audio:sound(staffAudio,undefined,['Müşteri → personel','Personel → müşteri']),duration:8000}),
    b('Personel kapatınca BYE Verasist’e ulaşır','Telefon BYE’ı operatöre gönderir; operatör Verasist personel bacağını BYE ile kapatır. Aktif ses durur. Örnek paket operatör–Verasist personel bacağındadır.','BYE · telefon → operatör → Verasist',[N.ip202,N.switch,N.operator,N.vera],sip('BYE','staff',{seq:2}),['Staff hangup reaches Verasist','The phone sends BYE to the operator, which sends BYE on the Verasist staff leg. Active audio stops. The sample packet belongs to the operator–Verasist staff leg.']),
    b('Personel bacağının kapanışı onaylanır','Verasist 200 OK döndürür; operatör telefonun BYE işlemini de kendi yanıtıyla tamamlar. Telefonun operatör kaydı silinmez.','200 OK · personel BYE',[N.vera,N.operator,N.switch,N.ip202],sip('BYE','staff',{status:'200 OK',seq:2}),['The staff leg closure is confirmed','Verasist returns 200 OK, and the operator separately completes the phone BYE transaction. Phone registration at the operator is retained.']),
    b('Verasist müşteri bacağını kapatır','Verasist müşteri bacağında operatöre BYE gönderir. Aynı görüşmedeki personel ve müşteri SIP bacakları ayrı ayrı kapatılır; müşteri hattı açık bırakılmaz.','BYE · Verasist → operatör',[N.vera,N.operator],sip('BYE','customer',{seq:2}),['Verasist closes the customer leg','Verasist sends BYE to the operator on the customer leg. Staff and customer SIP legs are ended separately so the customer line is not left open.']),
    b('Çağrı biter, telefon operatörde kayıtlı kalır','Operatör 200 OK döndürür. Verasist’in çağrı kaynakları temizlenir ve ses akışı biter. Telefon kayıt yenilemelerine operatörle devam eder; hiçbir aşamada kurum santrali veya Verasist telefon kaydı kullanılmadı.','200 OK · görüşme tamamlandı',[N.operator,N.vera],sip('BYE','customer',{status:'200 OK',seq:2}),['The call ends; the phone stays registered at the operator','The operator returns 200 OK. Verasist cleans up call resources and audio stops. The phone continues refreshing its operator registration. No office PBX or phone registration with Verasist was used.'],{final:true})
  ];
  const phoneWires=[
    {a:N.caller,b:N.operator,type:'access',title:'Operatör erişimi',description:'Müşterinin mobil veya sabit hat erişimi.'},
    {a:N.operator,b:N.switch,type:'sip',title:'Operatör ↔ modem / NAT',description:'İnternet üzerinden telefonun SIP ve RTP erişimi. Operatörün registrar/telefon hizmeti kullanılır; modem santral değildir.'},
    {a:N.switch,b:N.ip201,type:'ethernet',title:'RJ45 · IP telefon 201',description:'Telefonun modem/LAN bağlantısı; telefon hesabı operatördedir.'},
    {a:N.switch,b:N.ip202,type:'ethernet',title:'RJ45 · ayrı personel IP telefonu 202',description:'İkinci fiziksel IP telefon 202, office-a-202 hesabıyla operatöre kayıtlıdır. Ayrı 12025550201 numarası bu telefona gider; Verasist’e yönlendirilmez.'}
  ];
  return {id:'direct',labels:{tr:{[N.ip201]:'Ana telefon · 201',[N.ip202]:'Personel telefonu · 202'},en:{[N.ip201]:'Main phone · 201',[N.ip202]:'Staff phone · 202'}},descriptions:{tr:{[N.ip201]:'İlk çağrıyı alan fiziksel IP telefon 201. Ana 12025550101 numarası Verasist’e yönlendirilince bu numaradan çalmaz; Verasist aktarımı bu telefona dönmez.',[N.ip202]:'Farklı fiziksel IP telefon 202. Ayrı office-a-202 hesabıyla operatöre kaydolur; yönlendirilmemiş 12025550201 personel numarası bu telefona ulaşır.'},en:{[N.ip201]:'Original physical IP phone 201. Once main number 12025550101 routes to Verasist, this number no longer rings this handset. Verasist does not transfer back to it.',[N.ip202]:'Different physical IP phone 202. It registers at the operator with its own office-a-202 account; separate unforwarded staff number 12025550201 reaches it.'}},target:targets[0],phases,notice:'Bu örnek, operatörün telefon kaydı, Verasist’e gelen çağrı yönlendirmesi ve farklı IP telefon 202’ye ayrı personel numarasıyla ulaşmayı desteklediğini varsayar. Ana numara Verasist’e; personel numarası ikinci telefona gider.',noticeEn:'This example assumes operator support for phone registration, inbound routing to Verasist and a separate staff number for a different IP phone 202. The main number goes to Verasist; the staff number goes to the second phone.',topology:{stages:{
    operator:{stageLabel:{tr:'1/2 · Operatör ve IP telefon',en:'1/2 · Operator and IP phone'},nodeIds:[N.caller,N.operator,N.switch,N.ip201,N.ip202],connections:phoneWires},
    verasist:{stageLabel:{tr:'2/2 · Verasist eklendi',en:'2/2 · Verasist added'},nodeIds:[N.caller,N.operator,N.switch,N.ip201,N.ip202,N.vera],connections:[...phoneWires,{a:N.operator,b:N.vera,type:'sip',title:'Operatör ↔ Verasist SIP bağlantısı',description:'Ana numara Verasist’e yönlenir. Personel için Verasist’in açtığı ikinci bacak yine bu operatöre gider; telefon modem üzerinden operatöre kayıtlı kalır.'}]}
  }}};
}

function registrationScenario(mode) {
  const register = (title, text, message, path, code) => step(title, text, message, path, { code, type: 'registration' });
  const phonePath = [N.ip201, N.switch, N.pbx];
  const refresh = 'REGISTER sip:pbx.example.invalid SIP/2.0\nTo: <sip:201@pbx.example.invalid>\nContact: <sip:201@192.0.2.21:5060>\nExpires: 300\nCSeq: 2 REGISTER\nAuthorization: Digest username="201", realm="office", nonce="demo-nonce", response="<hesaplanan özet>"\nContent-Length: 0';
  const trunk = 'REGISTER sip:pbx.example.invalid SIP/2.0\nTo: <sip:verasist-trunk@pbx.example.invalid>\nContact: <sip:verasist-trunk@203.0.113.10:5060>\nExpires: 300\nCSeq: 2 REGISTER\nAuthorization: Digest username="verasist-trunk", realm="office", nonce="demo-nonce", response="<hesaplanan özet>"\nContent-Length: 0';
  const phases = mode === 'phones' ? [
    register('Önce kurumun sanal santrali hazırlanır', 'Bu örnekte telefonlar kuruma özel sanal santrale kaydolur; her telefona ayrı hesap açılır. Verasist’in mevcut bulut trunk ekranı bu hesapları açmaz. Ayrı santral zorunlu değildir: operatöre bağlı telefonun Verasist ile kullanımı Santralsiz IP telefon sekmesindedir.', 'Endpoint + Auth + AOR', [N.pbx], '201 / 202: ayrı kimlik ve parola\n301: hesabı ATA kullanır\nRegistrar: kuruma özel sanal santral\nBu kurulum mevcut panelde otomatik sunulmaz.'),
    register('Telefon kayıt isteğini gönderir', '201 telefonu, registrar adresine REGISTER gönderir. Amaç numarayı o an ulaşılabilen Contact adresiyle eşlemektir; arama veya ses başlamaz.', 'REGISTER · 201', phonePath, 'REGISTER sip:pbx.example.invalid SIP/2.0\nTo: <sip:201@pbx.example.invalid>\nContact: <sip:201@192.0.2.21:5060>\nExpires: 300\nCSeq: 1 REGISTER\nContent-Length: 0'),
    register('Santral kimlik doğrulama ister', '401 Unauthorized bu örnekte normal kimlik doğrulama adımıdır. Santral realm ve tek kullanımlık nonce bilgisi gönderir; kayıt henüz tamamlanmadı.', '401 · Digest challenge', [...phonePath].reverse(), 'SIP/2.0 401 Unauthorized\nWWW-Authenticate: Digest realm="office", nonce="demo-nonce", algorithm=MD5\nCSeq: 1 REGISTER\nContent-Length: 0'),
    register('Telefon doğrulama özetini gönderir', 'Telefon kullanıcı adı, parola ve challenge bilgisiyle Digest yanıtını hesaplar. Parola başlıkta düz metin gönderilmez. Bu temsili örnekte REGISTER CSeq değeri artar.', 'REGISTER + Authorization', phonePath, refresh),
    register('Dahili adresi kaydedilir', 'Santral doğrulamayı yapar, 201 AOR’unun Contact adresini ve süresini kaydeder. 200 OK kayıt başarısıdır; görüşme cevabı değildir. REGISTER için ACK gönderilmez.', '200 OK · kayıt başarılı', [...phonePath].reverse(), 'SIP/2.0 200 OK\nTo: <sip:201@pbx.example.invalid>;tag=registrar\nContact: <sip:201@192.0.2.21:5060>;expires=300\nCSeq: 2 REGISTER\nContent-Length: 0'),
    register('Diğer telefonlar da ayrı kaydolur', '202 kendi hesabıyla aynı işlemi yapar. Analog 301 adına ATA kaydolur; analog telefonun RJ11 kablosunda SIP yoktur. Her uç ayrı Contact kaydı taşır.', 'REGISTER · ATA / 301', [N.ata, N.switch, N.pbx], '202 → ayrı Endpoint/Auth/AOR\nATA → 301 hesabıyla REGISTER\nAnalog telefon ↔ ATA: RJ11 / FXS\nAnalog telefondan REGISTER çıkmaz.'),
    register('Süre dolmadan kayıt yenilenir', 'Telefonlar süre dolmadan REGISTER’ı yeniler. Kurumda statik genel IP zorunlu olmayabilir; erişilebilir registrar, NAT/keepalive ve medya ayarları gerekir. CGNAT durumunda VPN veya SBC gerekebilir.', 'REGISTER · yenileme', phonePath, refresh.replace('CSeq: 2', 'CSeq: 3')),
    register('Santral Verasist’e ayrı bağlanır', 'Telefonlar sanal santralde kalır. Verasist için ayrı trunk, ajan numarası ve arama rotası tanımlanır. REGISTER yalnızca ulaşılabilirlik kaydıdır; ses INVITE/SDP ile görüşme kurulunca RTP üzerinden akar.', 'Trunk + çağrı rotası', [N.pbx, N.vera], 'Telefon → kurum sanal santrali → Verasist\nDoğrudan bulut telefon kaydı: mevcut panelde desteklenmiyor.\nTrunk yöntemi: diğer bağlantı senaryosunda.\nBu adımlarda RTP sesi yok.')
  ] : [
    register('Mevcut santral ve trunk hesabı hazırlanır', 'IP telefonlar ve ATA kurum santralinde kalır. Bu örnekte kurum santrali registrar olur, Verasist’e özel trunk hesabı verir. Santralin bu yöntemi desteklemesi ve Verasist’ten erişilebilir olması gerekir.', 'Santral: registrar / Verasist: istemci', [N.pbx], 'Kurum santrali: trunk hesabı + yetkili çağrı rotası\nVerasist: gateway adresi/portu, kullanıcı adı, parola\nREGISTER yönü: Verasist → kurum santrali'),
    register('Verasist santrale kayıt isteği gönderir', 'Mevcut Verasist bağlayıcısındaki register seçeneği, Verasist’in karşı santrale REGISTER göndermesidir. Kurum santralinin Verasist’e kaydolması anlamına gelmez.', 'REGISTER · Verasist → santral', [N.vera, N.pbx], trunk.split('Authorization:')[0].replace('CSeq: 2', 'CSeq: 1') + 'Content-Length: 0'),
    register('Santral doğrulama ister', 'Kurum santrali 401 challenge döndürür. Verasist yapılandırılan trunk kimliğiyle Digest doğrulamasını hesaplar.', '401 · santral challenge', [N.pbx, N.vera], 'SIP/2.0 401 Unauthorized\nWWW-Authenticate: Digest realm="office", nonce="demo-nonce", algorithm=MD5\nCSeq: 1 REGISTER\nContent-Length: 0'),
    register('Verasist kimliğini doğrular', 'Verasist yeni REGISTER içinde Authorization gönderir. Telefonların 201/202 parolaları değil trunk hesabının kimliği kullanılır.', 'REGISTER + Authorization', [N.vera, N.pbx], trunk),
    register('Santral trunk Contact adresini kaydeder', 'Santral, trunk hesabını Verasist Contact adresine eşler ve 200 OK döndürür. Bu sonuç tek başına gelen çağrı yetkisi, ajan seçimi veya sesin çalıştığını kanıtlamaz.', '200 OK · trunk kaydı', [N.pbx, N.vera], 'SIP/2.0 200 OK\nContact: <sip:verasist-trunk@203.0.113.10:5060>;expires=300\nCSeq: 2 REGISTER\nContent-Length: 0'),
    register('Gelen çağrı eşleşmesi ayrıca ayarlanır', 'Mevcut bağlayıcı gelen SIP’i gateway IP eşleşmesiyle tanır. REGISTER karşı yöne gönderilir; gelen çağrı için kurumun erişilebilir gateway/VPN/SBC adresi ayrıca doğru olmalıdır. Dinamik IP için yalnızca register seçeneğini açmak yeterli değildir.', 'IP eşleşmesi + ajan rotası', [N.pbx, N.vera], 'Gelen SIP: tanımlı gateway IP eşleşmesi\nAranan numara: kuruma atanmış ajan hedefi\nFirewall / NAT / RTP portları ayrıca yapılandırılır.\nDinamik IP / CGNAT: VPN veya SBC ile sabit erişim değerlendir.'),
    register('REGISTER her trunk için zorunlu değildir', 'Karşılıklı IP yetkilendirmeli trunk’ta REGISTER kapalı olabilir. Uçlar birbirinin izinli IP’sini ve çağrı rotasını tanır. Kurum santralinin Verasist’e REGISTER göndermesi için ayrıca inbound registrar desteği gerekir; mevcut panel bunu sağlamaz.', 'Alternatif · IP eşleşmeli trunk', [N.pbx, N.vera], 'Yöntem A: Verasist → santral REGISTER (santral destekliyorsa)\nYöntem B: erişilebilir IP/VPN/SBC üzerinden IP eşleşmesi\nKurum → Verasist REGISTER: mevcut panel akışı değil.\nSes: görüşme kurulmadan RTP yok.')
  ];
  phases[phases.length - 1].final = true;
  return { id: 'registration', registrationMode: mode, target: targets[0], phases, title: 'Telefon bağlantısı' };
}

export function nodeLabel(id, scenarioId, directMode) { if (scenarioId === 'direct' && directMode === 'forward' && id === N.operator) return 'Kurum operatörü · A'; if (scenarioId === 'direct') { if (id === N.switch) return 'Ethernet switch'; if (id === N.ip201) return 'IP telefon · 201'; if (id === N.ip202) return 'IP telefon · 202'; } if (scenarioId === 'registration' && id === N.pbx) return 'Kurumun sanal santrali'; return id === N.vera && scenarioId === 'extension' ? 'Verasist · dahili 700' : nodes[id].label; }
export function protocolFor(a, b) {
  if ([a,b].includes(N.provider) && [a,b].includes(N.operator)) return 'Operatörler arası erişim';
  if ([a, b].includes(N.media) && [a, b].includes(N.ai)) return 'WebSocket · binary raw PCMU / 8 kHz';
  if ([a, b].includes(N.media) && [a, b].includes(N.vera)) return 'Verasist iç medya köprüsü / kanal';
  const wire = connections.find(link => [link.a, link.b].includes(a) && [link.a, link.b].includes(b));
  return wire?.type === 'analog' ? 'Analog ses / RJ11' : wire?.type === 'access' ? 'Operatör erişimi' : 'RTP / UDP · G.711 örneği';
}
export function detailFor(scenario, phase) {
  if(scenario.connectionModel||scenario.phoneModel||scenario.fxoModel)return {title:phase.message,route:phase.path.map(id=>scenario.labels.tr[id]||nodeLabel(id,scenario.id)).join(' → '),code:phase.code,note:'Bağlantı modelinin sadeleştirilmiş başarılı çağrı örneği. Adresler ve kimlikler sentetiktir; ağ/SIP/ARI ayarları kurum ürününe göre doğrulanmalıdır. Kontrol ve ses ayrı akışlardır.'};
  if(phase.type==='platform')return {title:phase.message,route:phase.path.map(id=>scenario.labels.tr[id]).join(' → '),code:phase.code,note:'Verasist uygulama katmanının gerçek kod akışından sadeleştirilmiş örnek. Kimlikler sentetiktir; JSON alanları kavramsal gösterimdir, çalıştırılabilir API sözleşmesi değildir. Organizasyon/iş akışı çözümlemesi ham sesin yolu değildir.'};
  if (phase.type === 'public-line') return {title:phase.message,route:phase.path.map(id=>scenario.labels.tr[id] || nodeLabel(id,scenario.id)).join(' → '),code:phase.code,note:'Eğitim örneği. SIP/SDP ve RTP örnekleri yalnız B–Verasist bacağına aittir. Sabit/mobil erişim ve operatörler arası şebeke tek RTP oturumu değildir. Ana numara ile personel numarası ayrıdır; kurumda SIP kaydı veya ATA gerekmez.'};
  if (phase.type === 'trunk-number') return {title:phase.message,route:phase.path.map(id=>nodeLabel(id,scenario.id)).join(' → '),code:phase.code,note:'Temsili başarılı çağrı örneği; canlı paket kaydı değildir. Ana DID doğrudan Verasist’e, ayrı personel DID’si kurum santraline gider. Her SIP bacağı ayrı Call-ID ve medya bilgisi taşır. Operatörün bu rotaları desteklemesi gerekir.'};
  if (phase.type === 'direct') return {title:phase.message, route:phase.path.map(id=>nodeLabel(id,scenario.id,scenario.directMode)).join(' → '), code:phase.code, note:'Operatör destekli örnek akış. Telefon operatöre kayıtlı kalır; Verasist’te telefon hesabı açılmaz. Ayrı SIP bacakları farklı Call-ID ve medya adresleri taşır. REGISTER ses başlatmaz. Ana numara ve personele dönüş hedefi ayrıdır.'};
  if (phase.type === 'engine') return { title: phase.message, route: phase.path.map(id => nodeLabel(id, scenario.id)).join(' → '), code: phase.code, note: 'Verasist iç mekanizmasının sadeleştirilmiş gösterimi. Alanlar ve kanal kimlikleri temsili; çalıştırılabilir API isteği değildir. Kontrol mesajları ile konuşma sesi ayrı taşınır.' };
  if (phase.type === 'registration') return { title: phase.message, route: phase.path.map(id => nodeLabel(id, scenario.id)).join(' → '), code: phase.code, note: 'Kayıt mesajları temsili ve kısaltılmıştır. Digest algoritması uçların desteğine göre seçilir. REGISTER ses taşımaz ve ACK gerektirmez. Kaynak: Asterisk PJSIP Configuration Sections and Relationships / Configuring Outbound Registrations.' };
  const destination = scenario.target.id;
  const from = phase.path[0], to = phase.path.at(-1);
  const route = phase.path.map(id => nodeLabel(id, scenario.id)).join(' → ');
  if (phase.type === 'media') return { title: 'Sesin gidiş ve dönüşü', route, code: 'RTP v2 | PT=0 (PCMU/8000 örneği)\nSequence: 420 → 421 → 422\nTimestamp: 160000 → 160160 → 160320\nSSRC: her medya kaynağı için ayrı\n20 ms örneği: 12 B RTP başlığı + 160 B ses\n\nRTP için paket başına SIP ACK beklenmez.', note: 'Yeşil ve turuncu iki ses yönünü gösterir. ATA’da RTP ↔ analog dönüşümü olur; RJ11’de IP paketi yoktur. Verasist’in içinde RTP → raw WebSocket ses → konuşma pipeline’ı dönüşümü yapılabilir; yanıt ters yönden döner.' };
  if (phase.type === 'analog') return { title: phase.message, route, code: 'ATA / FXS ↔ RJ11 ↔ analog telefon\nZil gerilimi / off-hook / analog ses\nIP, UDP, SIP ve RTP başlığı: YOK', note: 'SIP hesabını analog telefon değil ATA kullanır. ATA analog hat durumunu SIP çağrı durumuna dönüştürür.' };
  if (phase.type === 'internal') return { title: 'Verasist iç işlemi', route: 'Verasist içinde', code: JSON.stringify({ operation: phase.message, call: 'demo-call', destination, channels: phase.message.startsWith('Bridge') ? ['customer-leg', 'staff-leg'] : undefined }, null, 2), note: 'Kavramsal uygulama verisidir; çalıştırılabilir API sözleşmesi değildir. Bu kutu bir ağ ses paketi göstermez.' };
  if (phase.type === 'access' || phase.type === 'guide') return { title: 'Operatör erişimi', route, code: 'Arayan cihaz → operatör erişim ağı\nMobil veya sabit hat olabilir.\nBu bacak için SIP / IP başlığı varsayılmıyor.', note: 'Sonraki bacakta operatör SIP trunk kullanır. IP telefonlar Ethernet, analog telefon ATA/FXS üzerinden santrale bağlıdır.' };
  const requestMethod = /REFER/.test(phase.message) ? 'REFER' : /NOTIFY/.test(phase.message) ? 'NOTIFY' : /BYE/.test(phase.message) ? 'BYE' : /^ACK/.test(phase.message) ? 'ACK' : 'INVITE';
  const status = phase.message.match(/^(180|200|202)/)?.[1];
  const reasons = { 180: 'Ringing', 200: 'OK', 202: 'Accepted' };
  const cseq = requestMethod === 'BYE' ? 3 : requestMethod === 'NOTIFY' ? 2 : 1;
  const aiLeg = scenario.id === 'mechanism' && phase.path.length === 2 && phase.path.includes(N.vera) || requestMethod === 'INVITE' && (to === N.vera || from === N.vera && (phase.message.includes('YZ') || phase.message.includes('Verasist')));
  const user = requestMethod === 'REFER' ? 'pbx' : aiLeg ? '12025550100' : phase.message === 'INVITE · kurumun ana numarası' ? '12025550101' : destination;
  const host = to === N.vera ? 'verasist.example.invalid' : 'pbx.example.invalid';
  const first = status ? `SIP/2.0 ${status} ${reasons[status]}` : `${requestMethod} sip:${user}@${host} SIP/2.0`;
  const lines = [first, 'Via: SIP/2.0/UDP 192.0.2.10:5060;branch=z9hG4bK-demo;rport', `From: <sip:demo-caller@pbx.example.invalid>;tag=demo-a`, `To: <sip:${user}@${host}>${status || requestMethod === 'ACK' ? ';tag=demo-b' : ''}`, `Call-ID: demo-${aiLeg ? 'ai' : 'office'}-leg@pbx.example.invalid`, `CSeq: ${cseq} ${requestMethod}`];
  if (requestMethod === 'REFER' && !status) lines.push('Refer-To: <sip:700@pbx.example.invalid>');
  let body = '';
  if (requestMethod === 'NOTIFY' && !status) { lines.push('Event: refer', 'Subscription-State: terminated;reason=noresource', 'Content-Type: message/sipfrag;version=2.0'); body = 'SIP/2.0 200 OK\r\n'; }
  if (requestMethod === 'INVITE' && (!status || status === '200')) { lines.push('Content-Type: application/sdp'); body = 'v=0\r\no=- 1 1 IN IP4 203.0.113.20\r\ns=demo\r\nc=IN IP4 203.0.113.20\r\nt=0 0\r\nm=audio 10000 RTP/AVP 0\r\na=rtpmap:0 PCMU/8000\r\na=sendrecv\r\n'; }
  lines.push(`Content-Length: ${new TextEncoder().encode(body).length}`);
  return { title: phase.message, route: `${nodeLabel(from, scenario.id)} → ${nodeLabel(to, scenario.id)}\n${route}`, code: lines.join('\r\n') + '\r\n\r\n' + body, note: 'Sadeleştirilmiş tek SIP bacağı örneği. Santral/B2BUA diğer bacakta Call-ID, CSeq ve adresleri yeniden oluşturabilir. Başlıklar ve adresler sentetiktir; gerçek paket kaydı değildir.' };
}
